const EMPTY_ITEMS = [];
const EMPTY_DELIVERED = [];
const selectDeliveredInboxItems = (conversationId) => (state) => state.conversationInbox?.deliveredByConversationId?.[conversationId] ?? EMPTY_DELIVERED;
const selectInboxItems = (conversationId) => (state) => state.conversationInbox?.byConversationId[conversationId] ?? EMPTY_ITEMS;
const selectInboxWaitingCount = (conversationId) => (state) => {
  const items = state.conversationInbox?.byConversationId[conversationId];
  if (!items) return 0;
  let n = 0;
  for (const i of items) {
    if (i.status === "sending" || i.status === "pending") n++;
  }
  return n;
};
const selectInboxItemStatus = (conversationId, injectionId) => (state) => state.conversationInbox?.byConversationId[conversationId]?.find(
  (i) => i.injectionId === injectionId
)?.status ?? null;
function isStrandablePersonLine(item) {
  return item.kind === "user_message" && item.status === "pending" && item.isVisibleToUser;
}
export {
  isStrandablePersonLine,
  selectDeliveredInboxItems,
  selectInboxItemStatus,
  selectInboxItems,
  selectInboxWaitingCount
};
